#include <algorithm>
#include <cstdlib>
#include <iostream>
#include <vector>
using namespace std;
int main() {
    int cases;
    cin >> cases;
    while (cases--) {
        int relatives;
        cin >> relatives;
        vector<int> addresses(relatives);
        int addressSum = 0;
        for (int i = 0; i < relatives; ++i) {
            cin >> addresses[i];
            addressSum += addresses[i];
        }

        int home = addresses[relatives / 2];
        int distanceSum = 0;
        for (int address : addresses) distanceSum += abs(address - home);
        cout << distanceSum << '\n';
    }
    return 0;
}

